import{_ as t,o as a,c as n,ak as r}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse(`{"title":"Chainy game design: island lesson collection","description":"This is the working game design for the owner's November 11, 2026 direction.\\nIt replaces the economy-led progression direction and incorporates the owner's subsequent confirma","frontmatter":{"title":"Chainy game design: island lesson collection","description":"This is the working game design for the owner's November 11, 2026 direction.\\nIt replaces the economy-led progression direction and incorporates the owner's subsequent confirma","source":"docs/game-design-lesson-collection.md","category":"Game & system design","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/game-design-lesson-collection.md","filePath":"content/docs/game-design-lesson-collection.md"}`),i={name:"content/docs/game-design-lesson-collection.md"};function s(o,e,d,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[r(`<div><h1 id="chainy-game-design-island-lesson-collection">Chainy game design: island lesson collection<a class="header-anchor" href="#chainy-game-design-island-lesson-collection" aria-label="Link to this section">​</a></h1><p>This is the working game design for the owner&#39;s November 11, 2026 direction. It replaces the economy-led progression direction and incorporates the owner&#39;s subsequent confirmations: prerequisite order, three distinct minigames per world, sequential world unlocking, a required quiz, and offline AI teaching simulations. Detailed rules identified as implementation defaults are design recommendations chosen to make the specification executable; they are not additional owner confirmations. It describes the complete intended game, not a claim that the game is implemented or can be delivered within the remaining calendar time. <strong>Documentation and preparation only: Unity development waits for the owner&#39;s explicit final approval.</strong><a href="/Chainy-Docs/content/docs/documentation-index.html">Start here</a> · <a href="/Chainy-Docs/content/docs/project-baseline.html">Decisions</a> · <a href="/Chainy-Docs/content/docs/planning/a-z-complete-lesson-quiz-source-draft.html">Lesson source pack</a></p><h2 id="1-the-game-in-one-paragraph">1. The game in one paragraph<a class="header-anchor" href="#1-the-game-in-one-paragraph" aria-label="Link to this section">​</a></h2><p>Chainy is an offline, single-player Android exploration game for ages 12–17, initially in English. The player selects an unlocked world, starting with Web3, explores a compact 3D island, and follows 13 ordered lesson quests. Each lesson leads to a collectible learning object or a distinct minigame encounter. Completing the lesson records its term in that world&#39;s encyclopedia collection and activates the next quest. Recording all 13 terms finishes its collection and opens a required multiple-choice review. Completing that review finishes the world and unlocks the next one: Web3 → Blockchain → AI.</p><h2 id="2-confirmed-direction-and-implementation-defaults">2. Confirmed direction and implementation defaults<a class="header-anchor" href="#2-confirmed-direction-and-implementation-defaults" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Status</th><th>Rule</th></tr></thead><tbody><tr><td>Owner-directed</td><td>Main menu, world selector, then a 3D island with mobile joystick and buttons</td></tr><tr><td>Owner-directed</td><td>Speak to the tutorial NPC first to learn the island, controls, encyclopedia, quest log, and pause</td></tr><tr><td>Owner-directed</td><td>Explore freely after orientation; lesson completion follows one linear sequence within each world</td></tr><tr><td>Owner-directed</td><td>Exactly 13 lesson entries per world: 13 Web3, 13 Blockchain, and 13 AI, totaling 39</td></tr><tr><td>Owner-directed</td><td>Ordinary lessons are collectible objects; some lessons trigger unique minigames in separate scenes</td></tr><tr><td>Owner-directed</td><td>Minigames can require ordered item, NPC, and facility interactions</td></tr><tr><td>Owner-confirmed</td><td>Completing a lesson records its entry; after all 13 entries, a required quiz must be completed to finish the world</td></tr><tr><td>Prior owner direction retained</td><td>No functioning economy, shops, trading, or wallet balance system; these concepts can appear in fixed teaching examples</td></tr><tr><td>Owner-confirmed</td><td>Worlds unlock sequentially: Web3 first, then Blockchain, then AI</td></tr><tr><td>Owner-confirmed</td><td>Prerequisite-based lesson order and three distinct minigames per world, nine total</td></tr><tr><td>Owner-confirmed</td><td>Required review quiz; leaving before completion keeps the next world locked</td></tr><tr><td>Owner-confirmed</td><td>Offline AI teaching simulations are acceptable; no actual fitted model is required</td></tr><tr><td>Confirmed quiz rule</td><td>13 required questions per world, one per lesson; correct mistakes with feedback and retry until all 13 are resolved</td></tr><tr><td>Implementation default</td><td>Record first-response score separately from corrected completion; no percentage threshold, timer, or lives</td></tr><tr><td>Implementation default</td><td>Preserve successful checkpoints; unfinished minigames and abandoned quizzes restart their round on return</td></tr></tbody></table><p>The existing source pack supplies concepts and draft assessment seeds. Its older five-clusters-per-world sequence, compulsory per-term quizzes, shared-purchase prerequisite, and AI-as-stretch framing do not govern this new gameplay direction. Sections 14–15 provide concrete draft panel text and assessment content for implementation. Sean remains the documentation owner; these drafts have not received educator validation or established learning gains.</p><h2 id="3-player-journey">3. Player journey<a class="header-anchor" href="#3-player-journey" aria-label="Link to this section">​</a></h2><figure class="diagram"><div class="mermaid-source"><pre>flowchart TD
  Menu[Main menu] --&gt; Select[Select an unlocked world]
  Select --&gt; Load[Load selected world and saved progress]
  Load --&gt; Tutorial[First visit: tutorial NPC]
  Tutorial --&gt; Explore[Explore island and follow active quest]
  Load --&gt;|Returning visit| Explore
  Explore --&gt; Collect[Ordinary lesson: inspect and record object]
  Explore --&gt; Steps[Minigame lesson: ordered item, NPC, facility steps]
  Steps --&gt; Mini[Enter dedicated minigame scene]
  Mini --&gt;|Retry current round| Mini
  Mini --&gt;|Exit without completion| Explore
  Collect --&gt; Save[Save lesson and encyclopedia entry]
  Mini --&gt;|Success| Save
  Save --&gt;|Save failed| Retry[Retry save; do not advance]
  Retry --&gt; Save
  Save --&gt;|Fewer than 13| Explore
  Save --&gt;|13 recorded| Collection[Collection complete: quiz required]
  Collection --&gt; Quiz[Required 13-question review]
  Quiz --&gt;|Wrong answer: explanation and retry| Quiz
  Quiz --&gt;|Exit: next world remains locked| Select
  Quiz --&gt;|All questions resolved and saved| Complete[World complete: unlock next world]
  Complete --&gt; Select
</pre></div><figcaption><span>Diagram</span><button class="diagram-fullscreen">Full screen ↗</button><button class="diagram-expand" aria-expanded="false">Expand diagram</button><a href="#" class="diagram-toggle">Show source</a></figcaption></figure><p>Each world supplies its own fictional examples and explanations. No lesson assumes that the player has bought an item or studied a term in a different world. World unlocking controls access; lesson examples remain self-contained and do not require a shared purchase or transferable inventory.</p><h2 id="4-screens-and-controls">4. Screens and controls<a class="header-anchor" href="#4-screens-and-controls" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Screen or state</th><th>What the player sees and can do</th></tr></thead><tbody><tr><td>Main menu</td><td>Play opens world selection; Settings adjusts supported audio/accessibility settings; Quit exits on Android</td></tr><tr><td>World selection</td><td>Three named cards with recorded count, collection/quiz status, and Enter or Continue; locked cards explain which preceding world&#39;s quiz is required</td></tr><tr><td>Island exploration</td><td>Left joystick, contextual Interact button, current objective, Encyclopedia, Quest, and Pause buttons; fixed isometric camera</td></tr><tr><td>Tutorial/dialogue</td><td>Existing live-world dialogue overlay, short instructions and Next/Close choices; movement and world interactions blocked</td></tr><tr><td>Quest log</td><td>All 13 lessons in teaching order, completed entries, one current lesson, locked later lessons, and current step/location hint</td></tr><tr><td>Encyclopedia</td><td>World category tabs and 13 slots per category, recorded count, collected term explanations and examples</td></tr><tr><td>Lesson panel</td><td>Term name, short plain-language explanation, concrete example, and Record button</td></tr><tr><td>Minigame</td><td>Activity-specific touch controls, instructions, explanatory feedback, Retry, and Pause/Exit</td></tr><tr><td>Pause</td><td>Resume, controls reminder, sound settings, Return to world selection; no loss of already saved progress</td></tr><tr><td>Collection complete</td><td>13/13 recorded; Start required quiz, Keep exploring, or Return to world selection; next world stays locked</td></tr><tr><td>World completion</td><td>Collection and required quiz complete; Continue to next world or revisit this island; after AI show Journey complete</td></tr><tr><td>Review quiz</td><td>One multiple-choice question at a time; answer feedback, progress, exit, and final result</td></tr><tr><td>Loading/save failure</td><td>Clear status, Retry, and a safe route back where possible; no false completion or silent reset</td></tr></tbody></table><p>Recommended encyclopedia discovery display: locked slots show their letter and “Not recorded”; explanatory content unlocks only after lesson completion. World categories can be browsed from any island, but browsing never grants completion. The quest order and encyclopedia&#39;s A–Z display order are separate: teaching can follow prerequisites while the collection remains alphabetical.</p><h2 id="5-tutorial-and-exploration-rules">5. Tutorial and exploration rules<a class="header-anchor" href="#5-tutorial-and-exploration-rules" aria-label="Link to this section">​</a></h2><p>On the first visit to each world, the spawn area directs the player to its tutorial NPC. The player may move to the NPC, but lesson interactions stay locked until orientation finishes. The tutorial introduces movement, Interact, the active quest, collection, encyclopedia, and pause in short steps. Recommended interaction: ask the player to open and close Quest and Encyclopedia once, then finish orientation. Save tutorial completion separately for each world; offer the controls reminder on later visits. Closing before tutorial completion repeats orientation on return without granting lesson progress.</p><p>Retain the current visual direction: fixed orthographic isometric camera, restrained low-poly scenery, blue-haired yellow-clad Explorer, and screen-faced guides. Retain Sean as the Web3 guide, Matthew as the Blockchain guide, and Lee as the AI guide unless the owner changes them. Use a small island layout with visible landmarks and short routes, without jumping, combat, precision platforming, or a maze. Each current quest names its landmark and target object or NPC; a clearly distinguishable marker can guide exploration.</p><h2 id="6-lesson-and-collection-rules">6. Lesson and collection rules<a class="header-anchor" href="#6-lesson-and-collection-rules" aria-label="Link to this section">​</a></h2><p>The following checkpoint details are proposed implementation rules for the confirmed loop.</p><table><thead><tr><th>Lesson type</th><th>Ordered interaction</th><th>Completion</th></tr></thead><tbody><tr><td>Ordinary collection</td><td>Reach the active lesson object → Interact → inspect explanation/example → Record</td><td>Save the lesson completion and encyclopedia entry together</td></tr><tr><td>Minigame lesson</td><td>Follow its item/NPC/facility steps → launch its scene → satisfy its success rule → view explanation</td><td>Save minigame success, lesson completion, and encyclopedia entry together, then return to the island</td></tr></tbody></table><p>Only the current lesson can advance. Interacting with a later lesson shows a hint to finish the current quest and leaves the object available. Earlier recorded objects may show their entry again; they never increment the count twice. Ordinary lessons do not insert an extra compulsory quiz or require touching the object accidentally. Record confirms collection, not that the learner read, understood, or mastered the explanation.</p><p>Minigame prerequisite objects are temporary quest evidence, not an inventory/equipment system. Store their completed step flags; show the acquired item in the quest log rather than adding inventory management. An out-of-order NPC or facility interaction explains the missing step without launching the scene. No required item can be sold, spent, dropped, or permanently lost.</p><p>Each successful lesson activates exactly the next lesson in the same world. The completion transaction updates the entry, lesson, next objective, and collection-complete flag consistently. It does not mark the world complete or unlock the next world before the required quiz is resolved and saved. Until saving succeeds, show an explicit pending/error state and retain a retry route. The object may visibly change to Recorded only when the checkpoint succeeds.</p><h2 id="7-complete-lesson-route">7. Complete lesson route<a class="header-anchor" href="#7-complete-lesson-route" aria-label="Link to this section">​</a></h2><p>These tables preserve all 39 terms from the source pack in the prerequisite-based order selected for this implementation specification. They do not reduce the requirement to grouped lessons. The <code>LC</code> IDs are new identifiers; they do not reuse or reinterpret old V2 task or acceptance IDs. Once approved, keep each term&#39;s ID stable and store sequence separately if the order changes. Every entry uses the corresponding source-pack teaching point and page/source reference; props below are design proposals.</p><h3 id="web3-island-13-lessons">Web3 island: 13 lessons<a class="header-anchor" href="#web3-island-13-lessons" aria-label="Link to this section">​</a></h3><table><thead><tr><th>ID</th><th>Source letter and term</th><th>Encounter</th><th>Type</th></tr></thead><tbody><tr><td>LC-W01</td><td>F — Fiat Currency</td><td>Museum banknote display</td><td>Collect</td></tr><tr><td>LC-W02</td><td>C — Cryptocurrency</td><td>Fictional digital-coin placard</td><td>Collect</td></tr><tr><td>LC-W03</td><td>A — Altcoins</td><td>Coin comparison exhibit</td><td>Collect</td></tr><tr><td>LC-W04</td><td>X — XRP</td><td>Named-example display token</td><td>Collect</td></tr><tr><td>LC-W05</td><td>W — Wallets (Read-Only Awareness)</td><td>Address card → wallet guide → dummy terminal</td><td>Safe Address Handoff</td></tr><tr><td>LC-W06</td><td>I — Identity and Online Safety</td><td>Privacy shield card</td><td>Collect</td></tr><tr><td>LC-W07</td><td>Q — QR Codes in Web3</td><td>Non-scannable fictional poster</td><td>Collect</td></tr><tr><td>LC-W08</td><td>E — Exchanges (Know What, Not How)</td><td>Exchange information sign</td><td>Collect</td></tr><tr><td>LC-W09</td><td>J — Jupiter (JUP)</td><td>Named-service information plaque</td><td>Collect</td></tr><tr><td>LC-W10</td><td>V — Volatility (What It Means)</td><td>Chart strip → market guide → history display</td><td>Price Path</td></tr><tr><td>LC-W11</td><td>H — HODL</td><td>Slang postcard and explanation</td><td>Collect</td></tr><tr><td>LC-W12</td><td>R — Risks, Red Flags &amp; Staying Scam-Safe</td><td>Envelope → attendant → message kiosk</td><td>Message Inspector</td></tr><tr><td>LC-W13</td><td>U — Understanding Web3 Safety</td><td>Guide&#39;s safety checklist</td><td>Collect</td></tr></tbody></table><h3 id="blockchain-island-13-lessons">Blockchain island: 13 lessons<a class="header-anchor" href="#blockchain-island-13-lessons" aria-label="Link to this section">​</a></h3><table><thead><tr><th>ID</th><th>Source letter and term</th><th>Encounter</th><th>Type</th></tr></thead><tbody><tr><td>LC-B01</td><td>L — Ledger</td><td>Archive record book</td><td>Collect</td></tr><tr><td>LC-B02</td><td>B — Blockchain</td><td>Reference slip → archivist → workstation</td><td>Archive Reconstruction</td></tr><tr><td>LC-B03</td><td>D — Decentralization</td><td>Participant-network map</td><td>Collect</td></tr><tr><td>LC-B04</td><td>K — Keys (Public &amp; Private)</td><td>Public/secret information display</td><td>Collect</td></tr><tr><td>LC-B05</td><td>O — On-Chain vs Off-Chain</td><td>Two-location record diagram</td><td>Collect</td></tr><tr><td>LC-B06</td><td>G — Gas Fees</td><td>Fixed example fee receipt</td><td>Collect</td></tr><tr><td>LC-B07</td><td>T — Tokens (Not Toys!)</td><td>Access-token information tile</td><td>Collect</td></tr><tr><td>LC-B08</td><td>N — NFTs (Non-Fungible Tokens)</td><td>Unique-token exhibit</td><td>Collect</td></tr><tr><td>LC-B09</td><td>S — Smart Contracts</td><td>Rule card → facility keeper → condition console</td><td>Condition Machine</td></tr><tr><td>LC-B10</td><td>M — Mining &amp; Validators</td><td>Network-role exhibit</td><td>Collect</td></tr><tr><td>LC-B11</td><td>P — Proof Systems</td><td>Work/stake comparison board</td><td>Collect</td></tr><tr><td>LC-B12</td><td>Y — Your Data and Privacy in Web3</td><td>Public-record privacy panel</td><td>Collect</td></tr><tr><td>LC-B13</td><td>Z — Zero-Knowledge Proofs</td><td>Sealed credential → privacy guide → proof exhibit</td><td>Minimum Disclosure</td></tr></tbody></table><h3 id="ai-island-13-lessons">AI island: 13 lessons<a class="header-anchor" href="#ai-island-13-lessons" aria-label="Link to this section">​</a></h3><table><thead><tr><th>ID</th><th>Paired letter and AI term</th><th>Encounter</th><th>Type</th></tr></thead><tbody><tr><td>LC-A01</td><td>A — Artificial intelligence</td><td>Helper information terminal</td><td>Collect</td></tr><tr><td>LC-A02</td><td>D — Dataset</td><td>Fictional example-card tray</td><td>Collect</td></tr><tr><td>LC-A03</td><td>F — Feature</td><td>Annotated example display</td><td>Collect</td></tr><tr><td>LC-A04</td><td>L — Label</td><td>Example tray → lab assistant → labeling desk</td><td>Label Lab</td></tr><tr><td>LC-A05</td><td>T — Training</td><td>Training-process illustration</td><td>Collect</td></tr><tr><td>LC-A06</td><td>M — Model</td><td>Learned-pattern diagram</td><td>Collect</td></tr><tr><td>LC-A07</td><td>C — Classification</td><td>Category-output panel</td><td>Collect</td></tr><tr><td>LC-A08</td><td>P — Prediction</td><td>Prediction-versus-result card</td><td>Collect</td></tr><tr><td>LC-A09</td><td>V — Validation</td><td>Fresh-case pack → lab guide → test station</td><td>Test the Helper</td></tr><tr><td>LC-A10</td><td>B — Bias</td><td>Missing-example display</td><td>Collect</td></tr><tr><td>LC-A11</td><td>H — Human oversight</td><td>Human-review terminal</td><td>Collect</td></tr><tr><td>LC-A12</td><td>G — Generative AI</td><td>Reference sheet → editor NPC → text exhibit</td><td>Fact Patch</td></tr><tr><td>LC-A13</td><td>R — Responsible AI</td><td>Responsible-use checklist</td><td>Collect</td></tr></tbody></table><p>The AI terms are separately sourced additions, not chapters from the Web3 encyclopedia. Their matching letters do not make them equivalent to the original Web3/Blockchain terms. Named assets and services are informational examples, not endorsements, live tools, or investment instructions.</p><h2 id="8-nine-distinct-minigames">8. Nine distinct minigames<a class="header-anchor" href="#8-nine-distinct-minigames" aria-label="Link to this section">​</a></h2><p>The owner confirmed three distinct minigames in each world. The nine scene assignments below are implementation defaults with different player rules; shared loading, pause, input, feedback, and save code is appropriate. There is no minigame selection screen that bypasses its lesson encounter.</p><h3 id="safe-address-handoff-lc-w05">Safe Address Handoff: LC-W05<a class="header-anchor" href="#safe-address-handoff-lc-w05" aria-label="Link to this section">​</a></h3><p>After LC-W01–04, collect the fictional address card, speak to the wallet guide, then use the dummy terminal. The separate <code>MG_SafeAddressHandoff</code> scene is a routing puzzle, with a visible instruction that only the receiving address may leave the device. Three cards show a fictional receiving address, private signing key, and recovery phrase; all strings are visibly dummy examples and never resemble valid credentials. Tap the address card, then the Outgoing message slot; tap each secret card, then the Private storage slot. Submit the arrangement, then confirm the outgoing preview contains only the address. Success requires all three placements and the safe preview confirmation. An incorrect arrangement highlights which information would be exposed, keeps the puzzle open, and lets the player move that card. No network request, scanning, balance, payment, recovery flow, or actual wallet is present. After successful saving, record W and return beside the terminal with LC-W06 active.</p><h3 id="price-path-lc-w10">Price Path: LC-W10<a class="header-anchor" href="#price-path-lc-w10" aria-label="Link to this section">​</a></h3><p>After LC-W01–09, collect a chart strip, speak to the market guide, then use the history display. The separate <code>MG_PricePath</code> scene is a graph-reading activity using fictional units and no trading choices. The player taps two time markers to select the largest adjacent change on each of two labeled charts: chart A has values 10, 12, 7, 8; chart B has values 6, 6, 9, 8. Chart A&#39;s correct interval is time 2–3 with a change of 5; chart B&#39;s is time 2–3 with a change of 3. Use displayed numerical differences rather than requiring rapid mental arithmetic. The final future marker is blank; choose “Unknown: past changes do not guarantee the next value” instead of an asserted rise or fall. Success requires both intervals and the uncertainty statement; mistakes display the selected values and permit reselection. After successful saving, record V and return beside the display with LC-W11 active.</p><h3 id="message-inspector-lc-w12">Message Inspector: LC-W12<a class="header-anchor" href="#message-inspector-lc-w12" aria-label="Link to this section">​</a></h3><p>After LC-W01–11, collect a fictional envelope, speak to the kiosk attendant, then interact with the message kiosk. The separate <code>MG_MessageInspector</code> scene presents four fictional requests. For each, choose Continue, Verify, or Reject, then select the evidence supporting that choice.</p><table><thead><tr><th>Request</th><th>Expected action</th><th>Evidence</th></tr></thead><tbody><tr><td>Known island guide asks the player to read a public island notice</td><td>Continue</td><td>Known source, public information, no secret or payment requested</td></tr><tr><td>Someone requests the player&#39;s secret to unlock free coins</td><td>Reject</td><td>Request for a secret</td></tr><tr><td>An unknown poster promises a prize through a link</td><td>Verify</td><td>Source/destination is unverified; no real link is opened</td></tr><tr><td>A message claims an asset&#39;s future value is guaranteed</td><td>Reject</td><td>Unsupported guarantee</td></tr></tbody></table><p>Success requires the correct action and evidence for all four requests. An incorrect choice explains the overlooked evidence and allows retrying that request. The lesson teaches judgment about the displayed information; Continue is not a universal guarantee that a real message is safe. After successful saving, record the R entry and return the player beside the kiosk with LC-W13 active.</p><h3 id="archive-reconstruction-lc-b02">Archive Reconstruction: LC-B02<a class="header-anchor" href="#archive-reconstruction-lc-b02" aria-label="Link to this section">​</a></h3><p>After LC-B01, collect a reference slip, speak to the archivist, then use the archive workstation. The separate <code>MG_ArchiveReconstruction</code> scene shows checkpoint C0, three block cards, and a trusted reference for a fictional record field. The introductory panel explains a previous-block reference before asking the player to arrange the cards. Each card has a visible ID and previous-reference label: B1 follows C0, B2 follows B1, and B3 follows B2. Tap-select a card, tap its slot, and submit the order. Then compare two versions of a field against the trusted reference and select the altered field. Finally choose the explanation that a mismatch requires investigation against that reference.</p><p>Success requires the order, altered-field selection, and explanation to be correct. Feedback points to the specific mismatched reference or field and permits correction. This is a local record-linking and comparison exercise; labels are not cryptographic hashes, and a correct arrangement does not create consensus or prove historical truth. After successful saving, record the B entry and return beside the workstation with LC-B03 active.</p><h3 id="test-the-helper-lc-a09">Test the Helper: LC-A09<a class="header-anchor" href="#test-the-helper-lc-a09" aria-label="Link to this section">​</a></h3><p>After LC-A01–08, collect a fresh-case pack, speak to the lab guide, then use the test station. The separate <code>MG_TestHelper</code> scene prominently says “Scripted AI teaching simulation.” It presents three unfamiliar fictional delivery cases, the verified case details, and authored helper predictions. For each case, reveal the prediction, decide whether it matches the verified case, and correct any wrong category.</p><table><thead><tr><th>Verified example</th><th>Authored prediction</th><th>Expected review</th></tr></thead><tbody><tr><td>Complete address and matching destination; verified Routine</td><td>Routine</td><td>Matches</td></tr><tr><td>Destination mismatch; verified Review</td><td>Routine</td><td>Incorrect; change to Review</td></tr><tr><td>Missing address; verified Review</td><td>Review</td><td>Matches</td></tr></tbody></table><p>The final choice asks why checking only familiar training examples is insufficient: new cases may expose mistakes. Success requires correct review of all three cases and that explanation. Feedback contrasts prediction with evidence and allows retry; no real training occurs in this candidate. These practice cases are not a validated evaluation set and the results do not measure a real model&#39;s reliability. After successful saving, record the V entry and return beside the test station with LC-A10 active. Actual model training is outside this confirmed simulation-based implementation.</p><h3 id="condition-machine-lc-b09">Condition Machine: LC-B09<a class="header-anchor" href="#condition-machine-lc-b09" aria-label="Link to this section">​</a></h3><p>After LC-B01–08, collect a rule card, talk to the facility keeper, then use the condition console. The separate <code>MG_ConditionMachine</code> scene is a Boolean input-and-output puzzle, labeled “Contract-condition illustration; not a deployed smart contract.” Its displayed rule is “Open the demonstration locker only when permission is valid AND the request is unused.” For the three rounds, fixed inputs are valid/unused, valid/already used, and invalid/unused. Before running the illustration, select the expected Open or Stay closed lamp; the correct outputs are Open, Stay closed, Stay closed. After each selection, Run highlights both conditions and shows how the output follows the stated rule. Success requires all three correct predictions; an incorrect prediction receives the trace and retries that round. The example does not execute payment, mutate a wallet, or imply that all real contracts use this rule. After successful saving, record S and return beside the console with LC-B10 active.</p><h3 id="minimum-disclosure-lc-b13">Minimum Disclosure: LC-B13<a class="header-anchor" href="#minimum-disclosure-lc-b13" aria-label="Link to this section">​</a></h3><p>After LC-B01–12, collect a sealed fictional credential, speak to the privacy guide, then use the proof exhibit. The separate <code>MG_MinimumDisclosure</code> scene is a disclosure puzzle, prominently labeled “Concept illustration; no cryptographic proof is generated.” Each round shows a verifier&#39;s question, a closed credential, an authored verification seal, and optional detail tiles. Round one asks only whether an invented resident meets an age threshold; choose the Meets threshold seal while leaving exact birthday and full name covered. Round two asks only whether an invented visitor has entry permission; choose the Permission confirmed seal while leaving the private credential number and home address covered. The seal is explicitly assumed to come from a suitable verification system; hiding text alone does not prove a claim. Submit succeeds only when the requested seal is selected and every unneeded detail remains covered, then choose “The verifier checks the requested claim without receiving the underlying details.” Unnecessary disclosure or a wrong seal gives specific feedback and resets only the current round. After successful saving, record Z, return beside the exhibit, and offer the required Blockchain quiz because all 13 entries are now recorded.</p><h3 id="label-lab-lc-a04">Label Lab: LC-A04<a class="header-anchor" href="#label-lab-lc-a04" aria-label="Link to this section">​</a></h3><p>After LC-A01–03, collect the example tray, talk to the lab assistant, then use the labeling desk. The separate <code>MG_LabelLab</code> scene asks the player to attach known-answer stickers to four fictional training examples. Instructions show that a verified complete matching address is Routine, while a verified mismatch or missing address is Review. The four cases are complete/matching, missing address, complete/mismatched, and another complete/matching address; expected labels are Routine, Review, Review, Routine. Tap a sticker and then its example; submit the completed sheet. Incorrect stickers receive an evidence explanation and can be replaced individually. Success requires all four known labels and the final choice “A label is the known answer supplied with an example.” The scene states that this activity prepares labeled examples; it does not train a model or claim the player generated predictions. After successful saving, record L and return beside the desk with LC-A05 active.</p><h3 id="fact-patch-lc-a12">Fact Patch: LC-A12<a class="header-anchor" href="#fact-patch-lc-a12" aria-label="Link to this section">​</a></h3><p>After LC-A01–11, collect the reference sheet, talk to the editor NPC, then use the text exhibit. The separate <code>MG_FactPatch</code> scene is a sentence-repair activity labeled “Authored example of an AI response; no live generation.” The reference sheet says “Museum opens at 09:00; entry is free; delivery desk closes at 16:00.” The authored response says “Museum opens at 08:00; entry is free; delivery desk closes at 16:00; visitors must send a password.” Tap the incorrect opening time and replace it with 09:00 from the reference; keep the two supported clauses; remove the unsupported password instruction. The final response must contain exactly the three supported clauses and no password request. Choose the explanation “Generated-looking text can contain errors or unsupported instructions; compare it with trusted information.” Success requires the corrected response and explanation; feedback identifies the unsupported clause and allows editing without restarting the scene. After successful saving, record G and return beside the exhibit with LC-A13 active.</p><h3 id="shared-scene-lifecycle">Shared scene lifecycle<a class="header-anchor" href="#shared-scene-lifecycle" aria-label="Link to this section">​</a></h3><p>Save completed prerequisite steps before launch and remember the originating world, lesson, and safe return point. Disable repeated launch taps while loading; a load failure leaves the quest available to retry. Pause stops the activity; exit returns to the island without awarding that lesson. Completed prerequisite steps remain saved, so the player need not collect the same envelope/reference/case pack again. An unfinished minigame restarts its round on re-entry; mid-round resume is not promised. No timer, lives, spending, or permanent failure is required. A successful completion saves once before returning; if it fails, retain the result in memory and offer Retry Save or explicit discard of unsaved completion. If the app closes before a successful save, the lesson remains incomplete and the activity can be replayed. If the save succeeded but return/loading was interrupted, resume the island with the lesson already recorded. Revisiting a completed activity through its island encounter never creates a second entry or advances unrelated lessons.</p><h2 id="9-encyclopedia-completion-and-review-quiz">9. Encyclopedia, completion, and review quiz<a class="header-anchor" href="#9-encyclopedia-completion-and-review-quiz" aria-label="Link to this section">​</a></h2><p>The encyclopedia is a collection record of 39 entries, divided into the three 13-entry categories. Each recorded entry has its letter, exact source term, short meaning, example, and source attribution. Use “Recorded” and “World complete” rather than “Mastered.” Unrecorded entries do not count toward completion; a title visible in the quest log is not a collected entry.</p><p>A world&#39;s collection completes when its 13 required lesson entries have been successfully saved. Offer its required quiz immediately after that save, including when the thirteenth lesson is a minigame. The player may postpone the quiz to explore or leave, but the world remains “Quiz required” and the next world stays locked. The world completes only when the quiz is resolved and that completion is successfully saved. Unlock Blockchain after Web3 completion and AI after Blockchain completion; new profiles start with only Web3 available. Completed worlds remain available for exploration, encyclopedia review, and replays. Finishing AI produces “Journey complete: 39 entries recorded and three world reviews completed,” without claiming mastery or measured learning improvement.</p><p>The owner confirmed 13 required questions per world, one for each lesson, with correction retries until all are correct. Section 15 defines every required question in lesson order. Four options, one correct answer, no timer, and no percentage threshold are the specified presentation rules. On the first submission for an item, record whether it was correct, then show the explanatory reason. For a wrong response, keep that item active, allow the learner to consult the encyclopedia, and ask them to choose again until it is correct. Only a correct choice enables Next; all 13 must be resolved before Finish can save review completion and unlock the next world. The result shows “First responses: X/13; review completed after corrections,” keeping initial performance distinct from assisted correction. If Finish saving fails, retain the answers and show Retry Save; the next world remains locked until the transaction succeeds.</p><p>Leaving early records an abandoned attempt separately and preserves encyclopedia progress; it grants no quiz completion or unlock. An abandoned quiz restarts all 13 questions on return; partial first responses remain part of that abandoned attempt, not a completed score. Replay creates a new attempt and preserves previous completion and unlocks even if replay is abandoned. No quiz result is represented as school grading, proof of learning gain, or a validated assessment score.</p><h2 id="10-persistence-recovery-and-accessibility">10. Persistence, recovery, and accessibility<a class="header-anchor" href="#10-persistence-recovery-and-accessibility" aria-label="Link to this section">​</a></h2><p>Keep SQLite as the offline store and retain the simple local profile approach. No sign-in, teacher service, or network request is required to play. The minimal logical state is profile ID, content/schema version, per-world tutorial completion, active lesson/step, completed lesson IDs, encyclopedia entries, and separate quiz attempt/results including required-review completion. Collection completion derives from the 13 specified recorded lesson IDs, not raw interaction counts. World completion additionally requires a saved completed required review; access to the next world derives from that state. Save quiz completion and its unlock atomically so the world selector and persisted access cannot disagree. Minigame configuration and curriculum are authored content, not data supplied by a learner.</p><p>Store lesson completion and its encyclopedia entry atomically; duplicate taps and retries must be idempotent. On relaunch, use the last successful checkpoint and a safe island spawn near its objective, not an exact animation frame. Pause/encyclopedia/quest/dialogue overlays suspend world interaction and clear held joystick input before resuming. Android backgrounding pauses input and audio, attempts a safe checkpoint, and preserves the previous checkpoint if saving fails. Switching profiles clears the previous profile&#39;s in-memory progress before loading the next profile. Unknown or incompatible saved content must show a recovery message and preserve the old data rather than silently reset it. Existing saves are not automatically converted to 39-lesson completion; Christian must define and test any migration after reviewing the current schema.</p><p>Use readable text on the Android reference phone, large touch targets, text/icon feedback in addition to color, and equivalent essential information with sound muted. Use tap-to-select/place controls where dragging would require precision. The current baseline retains API 25 minimum installation and Android 10/API 29 reference testing; actual compatibility and performance require a named build and device checks.</p><h2 id="11-excluded-systems">11. Excluded systems<a class="header-anchor" href="#11-excluded-systems" aria-label="Link to this section">​</a></h2><p>No functioning economy, shop, trading, real wallet, cryptocurrency transaction, seed entry, public blockchain, or live exchange is needed. Fixed examples may explain fees, wallets, tokens, or contract conditions without implementing those services. No general inventory/equipment system, combat, multiplayer, competitive leaderboard, paid hints, cloud chatbot, or standalone Wordle/BlockMatch mode is required by this design. Teacher collection, transfer, upload, and app updates remain separate from offline gameplay.</p><h2 id="12-design-acceptance-cases">12. Design acceptance cases<a class="header-anchor" href="#12-design-acceptance-cases" aria-label="Link to this section">​</a></h2><p>These LC-G IDs define the new design&#39;s behavior; old V2-R and GP IDs keep their historical meaning.</p><table><thead><tr><th>ID</th><th>Observable check</th></tr></thead><tbody><tr><td>LC-G01</td><td>Main menu opens the world selector; new profiles can enter only Web3, and locked cards explain the required preceding review</td></tr><tr><td>LC-G02</td><td>A new world&#39;s tutorial must finish before collecting lessons; completed orientation is remembered per world</td></tr><tr><td>LC-G03</td><td>Each world has exactly its 13 specified unique terms; all 26 original terms and 13 distinct AI terms are retained</td></tr><tr><td>LC-G04</td><td>Only the current lesson advances; later-object interaction cannot collect or remove it</td></tr><tr><td>LC-G05</td><td>Ordinary collection shows meaning/example and records exactly once after successful save</td></tr><tr><td>LC-G06</td><td>Each minigame launches only through its ordered lesson prerequisites and returns to the correct island</td></tr><tr><td>LC-G07</td><td>There are exactly nine separate minigame scenes, three per world, each with distinct rules, explanatory retry, and its stated success condition</td></tr><tr><td>LC-G08</td><td>Failed/cancelled/loading-interrupted minigames do not award completion; completed prerequisite steps persist</td></tr><tr><td>LC-G09</td><td>Save failure does not advance the quest or claim a recorded entry; repeated retry cannot duplicate progress</td></tr><tr><td>LC-G10</td><td>Thirteen entries produce Collection complete / Quiz required; only a saved resolved required review marks World complete and unlocks the next world</td></tr><tr><td>LC-G11</td><td>Wrong answers retry the same item with feedback; first-response scores, assisted completion, and abandonment remain distinct; a replay cannot revoke an existing unlock</td></tr><tr><td>LC-G12</td><td>Closing after a saved lesson and reopening offline restores the entry, next objective, and world count</td></tr><tr><td>LC-G13</td><td>Two synthetic local profiles remain separate across world changes, app relaunch, and profile switching</td></tr><tr><td>LC-G14</td><td>Joystick/world interaction is blocked beneath overlays and while paused; background/resume does not leave stuck input</td></tr><tr><td>LC-G15</td><td>UI remains usable on the named reference phone with audio muted and without color-only instructions</td></tr><tr><td>LC-G16</td><td>No real secrets, financial transactions, public blockchain, or cloud model are requested; AI simulation is labeled accurately</td></tr><tr><td>LC-G17</td><td>Completing the first two worlds unlocks Blockchain then AI, while all previously completed worlds remain accessible</td></tr><tr><td>LC-G18</td><td>A minigame Retry stays inside its scene; Exit returns to its originating island without completion and with prerequisite flags preserved</td></tr><tr><td>LC-G19</td><td>Failure to save review completion leaves the next world locked and preserves the completed answers for Retry Save</td></tr></tbody></table><p>These checks require actual implementation evidence later and do not establish present completion.</p><h2 id="13-specification-and-content-readiness">13. Specification and content readiness<a class="header-anchor" href="#13-specification-and-content-readiness" aria-label="Link to this section">​</a></h2><p>The owner&#39;s decisions about world order, required quizzes, prerequisite-based lessons, nine minigames, and scripted AI are settled. They are not remaining clarification gates. The 13-question correction policy is confirmed. The detailed prop assignments, locked-entry display, checkpoint rules, and exact activity data remain specified proposals for documentation review. They may guide implementation only after the owner&#39;s final approval to begin development. If those defaults change, update this specification and its acceptance cases together rather than silently changing the runtime.</p><p>The route, activity rules, draft 39 lesson panels, and draft 39-question bank are concrete in this document. All 13 items per world in section 15 define the mandatory review payloads; no quiz-writing decision is left to the runtime. Final educator review, reading-load testing, visual assets, Unity scene wiring, and named-device acceptance are not established by authored content. Do not claim that a spawned agent, a finished document, or a completed card supplies that evidence. Sean remains the named documentation owner while agents prepare the implementation artifacts.</p><p>Current build evidence and the November 10 session outcome inform preparation and evidence records. The owner has explicitly limited current work to documentation and necessary setup. Unity development and implementation-agent execution require the owner&#39;s final approval after reviewing this documentation. The <a href="/Chainy-Docs/content/docs/planning/lesson-collection-delivery.html">execution plan</a> governs the parallel work and integration checks. The November 21, 2026 pre-final remains visible; preserve integration, QA, manuscript, and rehearsal time without promising unmeasured completion.</p><h2 id="14-draft-lesson-panel-payloads">14. Draft lesson panel payloads<a class="header-anchor" href="#14-draft-lesson-panel-payloads" aria-label="Link to this section">​</a></h2><p>Use the exact letter and title from section 7, the meaning and example below, and the corresponding citation/page locator in the <a href="/Chainy-Docs/content/docs/planning/a-z-complete-lesson-quiz-source-draft.html">lesson source pack</a>. Ordinary encounters show these before Record; minigame encounters show them before launch and make them available in the activity&#39;s help panel. A minigame entry is recorded only after its success rule and completion save. All examples are fictional; named service/asset examples retain the source book&#39;s historical context and are not instructions to use or buy anything. The underlying encyclopedia PDF has not been checked for this draft; these paraphrases use the repository&#39;s contents inventory and source pack.</p><h3 id="web3-panel-copy">Web3 panel copy<a class="header-anchor" href="#web3-panel-copy" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Lesson</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td>LC-W01</td><td>Fiat currency is money issued by a government; it can be physical cash or an ordinary bank balance.</td><td>Philippine pesos in a bank account are still fiat even when shown on a screen.</td></tr><tr><td>LC-W02</td><td>Cryptocurrency is a digital asset used on a cryptographic network; an in-game symbol is not automatically cryptocurrency or real money.</td><td>The island&#39;s demonstration coin icon has no cash value and cannot be spent outside this lesson.</td></tr><tr><td>LC-W03</td><td>Altcoins are cryptocurrencies other than Bitcoin; their names do not establish safety or future value.</td><td>Two named coins can have different purposes without either being guaranteed to rise in price.</td></tr><tr><td>LC-W04</td><td>XRP is a named cryptocurrency example in the source book, not government-issued money.</td><td>Recognizing the name does not require opening an account or buying it.</td></tr><tr><td>LC-W05</td><td>A wallet helps a user manage access and transactions; secret signing and recovery information must stay private.</td><td>A fictional receiving address may be shared, while a private key or recovery phrase must not be sent in a message.</td></tr><tr><td>LC-W06</td><td>Online safety includes protecting private information and checking who is making a request.</td><td>A stranger saying “verification” does not make it safe to reveal your password.</td></tr><tr><td>LC-W07</td><td>A QR code can encode a destination, but its appearance does not verify who controls that destination.</td><td>A prize poster&#39;s code needs its source checked before anyone follows it; this game opens no real code.</td></tr><tr><td>LC-W08</td><td>An exchange is a service where people trade digital assets; this lesson teaches recognition, not trading.</td><td>“Swap one coin for another” describes an exchange service, not a wallet backup.</td></tr><tr><td>LC-W09</td><td>The source book uses Jupiter as a named Solana swap-service example; it is not required to play Chainy.</td><td>An informational plaque describes the example without connecting to the service.</td></tr><tr><td>LC-W10</td><td>Volatility means a value can change substantially; a past increase does not guarantee a future one.</td><td>A fictional chart rises from 10 to 12 and then falls to 7; its next point is unknown.</td></tr><tr><td>LC-W11</td><td>HODL is slang for holding cryptocurrency, not a rule that guarantees a profit.</td><td>A slogan saying “HODL means prices must rise” supplies no evidence about tomorrow&#39;s price.</td></tr><tr><td>LC-W12</td><td>Requests for secrets, extreme urgency, suspicious links, and guaranteed rewards are warning signs.</td><td>A message demanding a recovery phrase within one minute to claim free coins should be rejected.</td></tr><tr><td>LC-W13</td><td>Pause, verify independently, and ask a trusted person when a Web3 request cannot be checked.</td><td>If a new wallet link cannot be verified, do not proceed just because a stranger insists.</td></tr></tbody></table><h3 id="blockchain-panel-copy">Blockchain panel copy<a class="header-anchor" href="#blockchain-panel-copy" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Lesson</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td>LC-B01</td><td>A ledger is a record of activity; compare conflicting entries with an accepted reference before relying on them.</td><td>A signed fictional reference says crate count 8 while one display says 6, so the discrepancy needs checking.</td></tr><tr><td>LC-B02</td><td>A blockchain groups records into linked blocks under network rules; checking a link is different from proving that an event happened.</td><td>The activity links B1 to checkpoint C0, B2 to B1, and B3 to B2, then checks a field against its reference.</td></tr><tr><td>LC-B03</td><td>Decentralization distributes control or recordkeeping among participants instead of one operator.</td><td>Three screenshots stored on one phone are still controlled on that phone; they are not three independent participants.</td></tr><tr><td>LC-B04</td><td>Public receiving information can be shared; private signing information authorizes actions and must be protected.</td><td>A demonstration address identifies where to receive, while its private key must remain secret.</td></tr><tr><td>LC-B05</td><td>On-chain activity is recorded on a blockchain; off-chain activity happens elsewhere.</td><td>Writing a private note in Chainy&#39;s local encyclopedia does not write anything to a public blockchain.</td></tr><tr><td>LC-B06</td><td>Some blockchain actions require a network-use fee separate from the price of an item.</td><td>A fixed example lists item price 8 and fee 1 as separate values; the game performs no purchase.</td></tr><tr><td>LC-B07</td><td>A token can represent a digital unit, access right, or item; its meaning depends on the system.</td><td>A fictional entry token may represent access without being real-world cash.</td></tr><tr><td>LC-B08</td><td>An NFT is a unique token record; that record alone does not guarantee value, copyright, or ownership of an underlying file.</td><td>A unique exhibit token does not guarantee that someone will buy it or that its holder owns the picture&#39;s copyright.</td></tr><tr><td>LC-B09</td><td>A smart contract is deployed code that follows its programmed conditions when executed with relevant inputs.</td><td>The lesson&#39;s locker opens only if permission is valid and the request is unused; the illustration is not a deployed contract.</td></tr><tr><td>LC-B10</td><td>Networks can use different participants and methods to propose and check blocks.</td><td>A network does not necessarily use both miners and validators doing the same job.</td></tr><tr><td>LC-B11</td><td>Proof of Work and Proof of Stake are different approaches used in network agreement systems.</td><td>A classroom tap or vote is not a real execution of either approach.</td></tr><tr><td>LC-B12</td><td>Public addresses and records can expose activity; a pseudonym is not a guarantee of anonymity.</td><td>An address with no printed name may still have publicly visible transactions.</td></tr><tr><td>LC-B13</td><td>A suitable zero-knowledge protocol can establish a claim without disclosing its underlying private details.</td><td>A verifier could learn that a threshold is met without receiving an exact birthday; this exhibit illustrates the idea without generating a proof.</td></tr></tbody></table><h3 id="ai-panel-copy">AI panel copy<a class="header-anchor" href="#ai-panel-copy" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Lesson</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td>LC-A01</td><td>AI systems can infer outputs such as predictions, recommendations, or generated content from inputs.</td><td>A helper predicting a request category illustrates an AI task; Chainy&#39;s authored demonstration is labeled as a simulation.</td></tr><tr><td>LC-A02</td><td>A dataset is a collection of examples; its quality and range matter.</td><td>Three copies of one delivery request do not provide the same variety as three different relevant requests.</td></tr><tr><td>LC-A03</td><td>A feature is an input detail a model can use to make a prediction.</td><td>An address mismatch is relevant to reviewing a delivery request; the card&#39;s decorative color is not relevant in this example.</td></tr><tr><td>LC-A04</td><td>A label is a known target answer supplied with a training example.</td><td>A verified past request marked Review has Review as its label.</td></tr><tr><td>LC-A05</td><td>During training, a learning method fits a model using examples.</td><td>Correcting an example&#39;s label can affect fitting; this scripted exhibit explains that process but does not train a model.</td></tr><tr><td>LC-A06</td><td>A trained model uses learned patterns to infer an output for a new input.</td><td>A fixed list of authored replies that never depends on examples is not a model trained by the player.</td></tr><tr><td>LC-A07</td><td>Classification predicts which defined category an input belongs to.</td><td>Predicting Routine or Review for a request is classification, not image generation.</td></tr><tr><td>LC-A08</td><td>A prediction is a proposed output that can be wrong and should be checked against appropriate evidence.</td><td>A helper&#39;s Routine suggestion disagrees with a verified Review case, so the suggestion needs correction.</td></tr><tr><td>LC-A09</td><td>Validation checks performance on examples separate from training; final test examples should stay untouched until final evaluation.</td><td>Getting familiar cards right does not establish that the helper handles new requests correctly.</td></tr><tr><td>LC-A10</td><td>Missing or skewed examples can contribute to systematically uneven results.</td><td>Adding more daytime requests may not fix errors on night requests when night examples are missing.</td></tr><tr><td>LC-A11</td><td>Human oversight means people retain responsibility and check consequential suggestions.</td><td>A person pauses a suggested dispatch when the address is missing, even if the helper says Routine.</td></tr><tr><td>LC-A12</td><td>Generative AI can produce text, images, and other content, but plausible content may contain errors.</td><td>An authored response says a museum opens at 08:00 while its trusted notice says 09:00; check the notice.</td></tr><tr><td>LC-A13</td><td>Responsible AI considers purpose, privacy, possible harm, fairness, and human control.</td><td>Practice with fictional examples instead of collecting real learner names when they are unnecessary.</td></tr></tbody></table><h2 id="15-draft-assessment-bank-and-required-review-payloads">15. Draft assessment bank and required review payloads<a class="header-anchor" href="#15-draft-assessment-bank-and-required-review-payloads" aria-label="Link to this section">​</a></h2><p>Question IDs are <code>Q-</code> followed by the corresponding lesson ID. The tables give exact draft wording, four ordered options, the correct option, and feedback. They paraphrase the corresponding source-pack checks and are implementation content, not a validated instrument. Options do not depend on live prices, actual accounts, personal information, or external websites.</p><p>The mandatory 13-question payloads follow the corresponding lesson order:</p><ul><li>Web3: Q-LC-W01 through Q-LC-W13.</li><li>Blockchain: Q-LC-B01 through Q-LC-B13.</li><li>AI: Q-LC-A01 through Q-LC-A13.</li></ul><p>Every question below is required in its world&#39;s review. A new attempt starts at question 1, including after abandoning an earlier attempt. Wrong answers are corrected within that attempt; they cannot be skipped to unlock a world.</p><h3 id="web3-question-bank">Web3 question bank<a class="header-anchor" href="#web3-question-bank" aria-label="Link to this section">​</a></h3><table><thead><tr><th>ID</th><th>Question</th><th>Four choices</th><th>Correct and feedback</th></tr></thead><tbody><tr><td>Q-LC-W01</td><td>Which example is fiat currency?</td><td>A: A fictional game badge; B: Philippine pesos in a bank account; C: A private key; D: An NFT picture</td><td>B. Government-issued money remains fiat when displayed digitally.</td></tr><tr><td>Q-LC-W02</td><td>The island displays a fictional coin teaching prop. What does that establish?</td><td>A: It is real cryptocurrency; B: It can be spent at a shop outside the game; C: It is a teaching symbol with no promised cash value; D: Its value will rise</td><td>C. The example does not create a real financial asset.</td></tr><tr><td>Q-LC-W03</td><td>What does “altcoin” refer to in this lesson?</td><td>A: A cryptocurrency other than Bitcoin; B: Any government banknote; C: A password backup; D: A guaranteed investment</td><td>A. The name identifies a broad category, not safety or value.</td></tr><tr><td>Q-LC-W04</td><td>How is XRP used in this course?</td><td>A: A required purchase; B: Government-issued money; C: A way to unlock the island; D: A named cryptocurrency example</td><td>D. Recognition is sufficient; no purchase or endorsement is involved.</td></tr><tr><td>Q-LC-W05</td><td>Which item may be included in the fictional receiving message?</td><td>A: The private signing key; B: The receiving address; C: The recovery phrase; D: The account password</td><td>B. Receiving information can be shared; signing and recovery secrets must stay private.</td></tr><tr><td>Q-LC-W06</td><td>A stranger asks for a password “to verify you.” What is the safe response?</td><td>A: Refuse and check through a trusted route; B: Send half the password; C: Send it if they hurry; D: Post it publicly</td><td>A. A verification claim does not justify sharing a secret.</td></tr><tr><td>Q-LC-W07</td><td>An unknown poster offers a prize through a QR code. What should happen first?</td><td>A: Follow it immediately; B: Enter a secret to see the prize; C: Share it with everyone; D: Check the source and destination through a trusted route</td><td>D. The code&#39;s appearance does not establish trust.</td></tr><tr><td>Q-LC-W08</td><td>A service swaps one digital asset for another. What is it describing?</td><td>A: A private key; B: A school attendance list; C: An exchange service; D: A wallet backup phrase</td><td>C. Trading and credential recovery are different functions.</td></tr><tr><td>Q-LC-W09</td><td>Must a learner use Jupiter to complete Chainy?</td><td>A: Yes, to pay the guide; B: No, it is an informational example; C: Yes, to save progress; D: Yes, to take the quiz</td><td>B. The source example does not require connecting to a service.</td></tr><tr><td>Q-LC-W10</td><td>A fictional asset rose in value yesterday. What follows about tomorrow?</td><td>A: It must rise again; B: It cannot fall; C: Its next value remains uncertain; D: Its value is guaranteed by its name</td><td>C. Past movement does not guarantee a future price.</td></tr><tr><td>Q-LC-W11</td><td>What does the slogan HODL establish?</td><td>A: It is slang for holding, without a guaranteed outcome; B: A legal promise of profit; C: A private key; D: A fixed future price</td><td>A. Slang is not evidence about future value.</td></tr><tr><td>Q-LC-W12</td><td>A message demands a recovery phrase within one minute for free coins. Which response is justified?</td><td>A: Send it before time runs out; B: Send only some words; C: Trust the free reward claim; D: Reject the request because it asks for a secret</td><td>D. The secret request and urgency are warning signs.</td></tr><tr><td>Q-LC-W13</td><td>You cannot verify a new wallet link. What is the next safe action?</td><td>A: Proceed because it looks professional; B: Enter a password to test it; C: Pause and seek trusted help; D: Assume every link is safe</td><td>C. Uncertainty calls for checking, not disclosure.</td></tr></tbody></table><h3 id="blockchain-question-bank">Blockchain question bank<a class="header-anchor" href="#blockchain-question-bank" aria-label="Link to this section">​</a></h3><table><thead><tr><th>ID</th><th>Question</th><th>Four choices</th><th>Correct and feedback</th></tr></thead><tbody><tr><td>Q-LC-B01</td><td>A reference says count 8, while a local record says 6. What should you do?</td><td>A: Automatically accept 6; B: Investigate the discrepancy against the reference; C: Delete all records; D: Assume both describe the same value</td><td>B. A mismatch calls for checking before reliance.</td></tr><tr><td>Q-LC-B02</td><td>What does correctly arranging the activity&#39;s linked block cards show?</td><td>A: A real network reached consensus; B: Every event in history is true; C: A public blockchain was created; D: The displayed previous-reference order is consistent</td><td>D. Local linking does not establish network agreement or historical truth.</td></tr><tr><td>Q-LC-B03</td><td>Are three screenshots on one phone three independent network participants?</td><td>A: No, they are copies controlled on one device; B: Yes, because there are three pictures; C: Yes, if colored differently; D: Only if renamed</td><td>A. Multiple local copies do not create independent control.</td></tr><tr><td>Q-LC-B04</td><td>Which information must remain secret in the example?</td><td>A: A public notice; B: The receiving address; C: The private signing key; D: The lesson title</td><td>C. Private signing information can authorize actions.</td></tr><tr><td>Q-LC-B05</td><td>A private encyclopedia note is stored only on this phone. Where is it recorded?</td><td>A: On every public blockchain; B: Off-chain in the local app; C: In a public consensus vote; D: In a real wallet transaction</td><td>B. Local storage does not create an on-chain record.</td></tr><tr><td>Q-LC-B06</td><td>A fixed receipt shows price 8 and network fee 1. What is the fee?</td><td>A: Proof the item is free; B: The item&#39;s name; C: A secret recovery word; D: A separate transaction cost</td><td>D. The displayed fee is separate from the listed item price.</td></tr><tr><td>Q-LC-B07</td><td>Must every token have real-world cash value?</td><td>A: Yes, if drawn as a coin; B: Yes, if rare; C: No, its meaning and rights depend on the system; D: Yes, if collected</td><td>C. A token can represent access or another unit without cash value.</td></tr><tr><td>Q-LC-B08</td><td>What does a unique NFT record guarantee by itself?</td><td>A: None of resale value, copyright, or ownership of an underlying file; B: A guaranteed profit; C: Automatic copyright ownership; D: Ownership of every copy of a picture</td><td>A. A token record alone does not establish those additional rights or outcomes.</td></tr><tr><td>Q-LC-B09</td><td>The locker rule requires valid permission AND an unused request. Permission is valid, but the request was used. What follows?</td><td>A: Open because one condition passed; B: Open if the player taps twice; C: Choose randomly; D: Stay closed because both conditions are required</td><td>D. The displayed rule requires both conditions to be true.</td></tr><tr><td>Q-LC-B10</td><td>Must every blockchain use miners and validators doing the same job?</td><td>A: Yes, always; B: No, roles depend on the network design; C: Only on phones; D: Only in a game</td><td>B. Networks use different methods and participant roles.</td></tr><tr><td>Q-LC-B11</td><td>Does tapping a card perform real Proof of Work or Proof of Stake?</td><td>A: Yes, every tap creates a block; B: Yes, if the card glows; C: No, it is only a teaching interaction; D: Yes, after collecting thirteen cards</td><td>C. An illustration does not execute a public network&#39;s agreement system.</td></tr><tr><td>Q-LC-B12</td><td>A public address has no printed real name. Is its activity necessarily private?</td><td>A: No, activity can still be visible or linked; B: Yes, a pseudonym hides everything; C: Yes, all ledgers are private; D: Only the owner can ever see it</td><td>A. A pseudonym is not a promise of anonymity.</td></tr><tr><td>Q-LC-B13</td><td>What could a suitable zero-knowledge system establish in the exhibit&#39;s example?</td><td>A: Everyone&#39;s birthday; B: A guaranteed identity from hidden text alone; C: A cryptocurrency price; D: That a threshold is met without revealing the exact birthday</td><td>D. A suitable protocol checks the claim; this game only illustrates that idea.</td></tr></tbody></table><h3 id="ai-question-bank">AI question bank<a class="header-anchor" href="#ai-question-bank" aria-label="Link to this section">​</a></h3><table><thead><tr><th>ID</th><th>Question</th><th>Four choices</th><th>Correct and feedback</th></tr></thead><tbody><tr><td>Q-LC-A01</td><td>Which task illustrates prediction by an AI helper?</td><td>A: Always printing a fixed title; B: Predicting a request&#39;s category from input details; C: Closing a menu; D: Drawing a static button</td><td>B. Prediction uses input information to propose an output; Chainy&#39;s example remains labeled as a simulation.</td></tr><tr><td>Q-LC-A02</td><td>What improves the range of a practice dataset?</td><td>A: Copying one card repeatedly; B: Changing only its border color; C: Including different relevant verified cases; D: Removing every difficult example</td><td>C. Relevant variety adds coverage that duplicate copies do not.</td></tr><tr><td>Q-LC-A03</td><td>Which feature is relevant to reviewing the fictional delivery request?</td><td>A: Whether its destination mismatches; B: Decorative card color; C: The screen border; D: The player&#39;s favorite music</td><td>A. Destination mismatch bears on this task&#39;s decision.</td></tr><tr><td>Q-LC-A04</td><td>A verified past request is marked Review. What is Review here?</td><td>A: A destination address; B: A private password; C: A new prediction; D: The example&#39;s known label</td><td>D. A label supplies the known target answer for an example.</td></tr><tr><td>Q-LC-A05</td><td>What happens during actual model training?</td><td>A: Every answer is guaranteed correct; B: A learning method fits a model using examples; C: A public blockchain is repaired; D: An authored caption becomes a trained model</td><td>B. Fitting depends on examples; showing a scripted answer is different.</td></tr><tr><td>Q-LC-A06</td><td>The game repeats authored replies regardless of supplied examples. Has the player trained a model?</td><td>A: Yes, because a robot appears; B: Yes, because a label was tapped; C: No, the replies do not result from fitting to those examples; D: Yes, if the scene is named AI</td><td>C. A simulation must not claim example-dependent training it does not perform.</td></tr><tr><td>Q-LC-A07</td><td>Predicting Routine or Review is which task?</td><td>A: Classification; B: Image generation; C: Mining; D: Wallet recovery</td><td>A. Classification selects among defined categories.</td></tr><tr><td>Q-LC-A08</td><td>A helper predicts Routine, but the verified case is Review. Which should guide this check?</td><td>A: The brighter button; B: The first prediction forever; C: The robot&#39;s appearance; D: The verified case evidence</td><td>D. A prediction can be wrong and must be checked.</td></tr><tr><td>Q-LC-A09</td><td>A helper gets every familiar training example right. Is that enough to claim it handles new cases?</td><td>A: Yes, familiar examples prove everything; B: No, check separate unfamiliar cases and inspect mistakes; C: Yes, if it is fast; D: Yes, if the cards are duplicated</td><td>B. Performance on familiar examples alone does not establish generalization.</td></tr><tr><td>Q-LC-A10</td><td>All examples are daytime requests and the helper often fails at night. What should be examined?</td><td>A: Only the card color; B: How to copy daytime cards faster; C: Whether relevant night examples are missing; D: How to hide the failures</td><td>C. Missing coverage can contribute to uneven results.</td></tr><tr><td>Q-LC-A11</td><td>A helper suggests dispatch despite a missing address. What should the person do?</td><td>A: Pause and check before allowing dispatch; B: Send automatically; C: Invent an address; D: Treat the suggestion as proof</td><td>A. Consequential actions require human judgment and adequate information.</td></tr><tr><td>Q-LC-A12</td><td>An authored AI response says 08:00, while the trusted museum notice says 09:00. What should the editor do?</td><td>A: Trust the response because it sounds confident; B: Delete the trusted notice; C: Assume both times mean the same thing; D: Correct the response using the notice</td><td>D. Plausible generated-looking text can conflict with reliable evidence.</td></tr><tr><td>Q-LC-A13</td><td>Fictional examples are enough for practice. Should the game collect real learner identities for that dataset?</td><td>A: Yes, more personal information is always better; B: No, avoid unnecessary personal data; C: Yes, to make the robot look realistic; D: Yes, without telling anyone</td><td>B. Responsible design uses only the data needed for the task.</td></tr></tbody></table></div>`,1)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
